queries:
SELECT e.status, AVG(b.amount - b.spent), COUNT(*)
FROM budget b
INNER JOIN event e ON b.link_to_event = e.event_id
WHERE b.spent > 6.0
GROUP BY e.status;
SELECT category FROM budget WHERE spent >= 6.0;
SELECT AVG(amount - spent), COUNT(*) FROM budget;
SELECT AVG(amount - spent) FROM budget WHERE amount IS NOT NULL AND spent IS NOT NULL
SELECT AVG(amount) - AVG(spent) FROM budget
SELECT e.status, SUM(b.spent) FROM event e JOIN budget b ON b.link_to_event = e.event_id GROUP BY e.status;
